const results = [];

// Real-estate qualification threshold.
// Leads with a minimum stated property budget of $750,000+
// are treated as Priority Buyers.
const PRIORITY_BUYER_THRESHOLD = 750000;

function cleanString(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function parseAmount(raw, inheritedUnit = '') {
  const num = Number(String(raw).replace(/,/g, ''));
  if (!Number.isFinite(num)) return 0;

  const unit = String(inheritedUnit || '').toLowerCase();

  if (unit === 'k') return Math.round(num * 1_000);
  if (unit === 'm') return Math.round(num * 1_000_000);

  return Math.round(num);
}

function parseBudget(value) {
  const text = cleanString(value).toLowerCase();

  if (!text) {
    return {
      min: 0,
      max: 0,
      value: 0
    };
  }

  // Handles ranges such as:
  // $600,000 - $800,000
  // $600k - $800k
  // 600,000 to 800,000
  // $600k to $800,000
  const range = text.match(
    /[$€£₹]?\s*([\d,.]+)\s*([km]?)\s*(?:-|–|—|to)\s*[$€£₹]?\s*([\d,.]+)\s*([km]?)/i
  );

  if (range) {
    const firstUnit = range[2] || '';
    const secondUnit = range[4] || firstUnit;

    const min = parseAmount(range[1], firstUnit);
    const max = parseAmount(range[3], secondUnit);

    const normalizedMin = Math.min(min, max);
    const normalizedMax = Math.max(min, max);

    return {
      min: normalizedMin,
      max: normalizedMax,
      value: normalizedMin
    };
  }

  // Handles single values such as:
  // $750,000
  // $750k
  // 750000
  const single = text.match(
    /[$€£₹]?\s*([\d,.]+)\s*([km]?)/i
  );

  if (!single) {
    return {
      min: 0,
      max: 0,
      value: 0
    };
  }

  const amount = parseAmount(single[1], single[2]);

  // A ceiling such as:
  // under $750k
  // below $750,000
  // less than $750k
  // up to $750k
  // should not qualify as a Priority Buyer.
  if (/\b(under|below|less than|up to|maximum|max)\b/i.test(text)) {
    return {
      min: 0,
      max: amount,
      value: 0
    };
  }

  // A floor such as:
  // $750k+
  // $750,000+
  // qualifies at the stated threshold.
  return {
    min: amount,
    max: amount,
    value: amount
  };
}

function validIsoDate(value) {
  const text = cleanString(value);

  if (!text) return null;

  const match = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);

  if (!match) return null;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  const date = new Date(Date.UTC(year, month - 1, day));

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  return text;
}

for (const item of $input.all()) {
  const name = cleanString(item.json.name);
  const email = cleanString(item.json.email).toLowerCase();
  const inquiryDetails = cleanString(item.json.inquiryDetails);
  const budgetRange = cleanString(item.json.budgetRange);
  const moveInDate = validIsoDate(item.json.moveInDate);
  const source = cleanString(item.json.source) || 'unknown';

  const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  const missingFields = [];

  if (!name) {
    missingFields.push('Name');
  }

  if (!email) {
    missingFields.push('Email');
  } else if (!emailValid) {
    missingFields.push('Valid Email');
  }

  if (!inquiryDetails || inquiryDetails.length < 10) {
    missingFields.push('Inquiry Details');
  }

  if (!budgetRange) {
    missingFields.push('Budget Range');
  }

  if (!moveInDate) {
    missingFields.push('Move-in Date');
  }

  const budget = parseBudget(budgetRange);

  let leadPriority = 'Standard Buyer';

  if (missingFields.length > 0) {
    leadPriority = 'Missing Info';
  } else if (budget.min >= PRIORITY_BUYER_THRESHOLD) {
    leadPriority = 'Priority Buyer';
  }

  results.push({
    json: {
      name,
      email,
      emailValid,
      inquiryDetails,
      budgetRange,
      budgetMin: budget.min,
      budgetMax: budget.max,
      budgetValue: budget.value,
      moveInDate,
      source,
      leadPriority,
      missingFields,
      qualifiedAt: new Date().toISOString()
    }
  });
}

return results;
